/**
 * workforce-avatar-art.ts -- LIGHT-BARREL duplicate of the workforce
 * avatar/status-dot art (`../../map/workforce-icon-art.ts`'s
 * `WORKFORCE_AVATAR_ART`), for the list-row NAME cell
 * (`live-mixed-columns.tsx`) and any other `views/live/` surface that needs
 * it. Duplicated rather than imported across the map boundary: this module
 * tree may only TYPE-import from `../../map/` (the heavy maplibre/deck.gl
 * entry, reached only through `views/MapView.tsx`'s `React.lazy` slot) --
 * see `live-data.ts`'s docblock for the full lazy-weight rule this mirrors.
 * The list row renders unconditionally (never lazy), so this bears its own
 * copy of just the 3 avatar variants -- NOT the map-marker pin art, which
 * stays map-only.
 *
 * Source: same vendored SVG exports as the map copy
 * (`/Users/apple/Desktop/Workforce icons`, `Group 1261154774/775/777.svg`).
 * Keep both copies in sync if the source art is ever replaced.
 */
export type WorkforceStatusKey = 'on-duty' | 'on-break' | 'in-transit' | 'clocked-in' | 'not-clocked-in'

export const WORKFORCE_AVATAR_ART_W = 41
export const WORKFORCE_AVATAR_ART_H = 45

export const WORKFORCE_AVATAR_ART: Record<WorkforceStatusKey, string> = {
  'on-duty': 'data:image/svg+xml;base64,',
  'on-break': 'data:image/svg+xml;base64,',
  'in-transit': 'data:image/svg+xml;base64,',
  'clocked-in': 'data:image/svg+xml;base64,',
  'not-clocked-in': 'data:image/svg+xml;base64,',
}

/**
 * Field vs office designation classifier + art-status resolver — light-
 * barrel duplicate of `../../map/live-types.ts`'s `isFieldDesignation` /
 * `resolveWorkforceArtStatus` (2026-09-01 workforce-coin fix), for the same
 * "may only TYPE-import across the map boundary" reason the rest of this
 * file is duplicated rather than imported (see docblock above). Keep in
 * sync if the field/office designation vocabulary changes.
 */
export function isFieldDesignation(designation?: string | null): boolean {
  return /field|inspector|patrol|driver|technician|crew/i.test(designation ?? '')
}

export function resolveWorkforceArtStatus(status: WorkforceStatusKey, designation?: string | null): WorkforceStatusKey {
  if (status === 'clocked-in' && isFieldDesignation(designation)) return 'on-duty'
  return status
}
